import React from 'react';
import {AbsoluteFill, Audio, Easing, Sequence, staticFile, useCurrentFrame} from 'remotion';
import {loadFont} from '@remotion/google-fonts/Inter';
import {loadFont as loadPoppins} from '@remotion/google-fonts/Poppins';
import content from './content.json';
import voTiming from './vo-timing.json';

// ---------------------------------------------------------------------------
// Editable text, colors, chart data and timing live in content.json (brand:
// DataEntropy guideline). vo-timing.json is generated by `npm run srt`.
// All motion is keyed to scene start frames, so moving a scene's `start`
// shifts its animations with it.
// ---------------------------------------------------------------------------

const {fontFamily} = loadFont('normal', {weights: ['400', '500', '600', '700'], subsets: ['latin']});
const FONT = `${fontFamily}, Arial, sans-serif`;
// The wordmark is set in a geometric sans (Poppins) to match the logo artwork.
const LOGO_FONT = `${loadPoppins('normal', {weights: ['700'], subsets: ['latin']}).fontFamily}, ${FONT}`;

const C = content.colors;
const FPS = content.fps;
const END = content.durationSeconds * FPS;
const S = content.scenes.map((s) => Math.round(s.start * FPS)); // scene start frames
const sceneEnd = (i: number) => (i + 1 < S.length ? S[i + 1] : END);

// Screen layout (brand safe area: 10% top, 18% bottom, 7% sides).
const SAFE = {left: 76, right: 1004};
const HEADLINE_Y = 250; // first headline baseline
const CONTENT_CY = 890; // screen y the camera centers content on (between headline and subtitles)
const SUB_BOTTOM = 1560;

// Easing: brand curve for things entering, ease-in-out for on-screen morphs,
// ease-in only for one-way exits, linear for time-based motion.
type Ease = (t: number) => number;
const EASE = {
	out: Easing.bezier(0.22, 1, 0.36, 1),
	inOut: Easing.bezier(0.645, 0.045, 0.355, 1),
	in: Easing.bezier(0.55, 0.055, 0.675, 0.19),
	linear: (t: number) => t,
};

// Keyframe track: kf(frame, [f0, f1, ...], [v0, v1, ...], easing), clamped.
// `easing` is one curve for all segments or an array with one per segment.
const kf = (f: number, frames: number[], values: number[], easing: Ease | Ease[] = EASE.inOut) => {
	if (f <= frames[0]) return values[0];
	const i = frames.findIndex((_, k) => k + 1 < frames.length && f < frames[k + 1]);
	if (i < 0) return values[values.length - 1];
	const e = Array.isArray(easing) ? easing[i] : easing;
	return values[i] + (values[i + 1] - values[i]) * e((f - frames[i]) / (frames[i + 1] - frames[i]));
};
const enter = (f: number, frames: number[], values: number[]) => kf(f, frames, values, EASE.out);
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
// Visible from a to b: enters on the brand curve, leaves faster on ease-in.
const fade = (f: number, a: number, b: number, dIn = 16, dOut = 8) =>
	Math.min(enter(f, [a, a + dIn], [0, 1]), kf(f, [b - dOut, b], [1, 0], EASE.in));

const mixColor = (a: string, b: string, t: number) => {
	const p = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
	const [x, y] = [p(a), p(b)];
	return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * t).toString(16).padStart(2, '0')).join('');
};

// "*word*" marks a highlighted word. Returns words with their highlight flag.
const parseMarked = (s: string) =>
	s.split(/(\*[^*]+\*)/).flatMap((part) => {
		const hl = part.startsWith('*');
		return part.replaceAll('*', '').split(/\s+/).filter(Boolean).map((w) => ({w, hl}));
	});
const spaced = (w: string, k: number) => (k > 0 && !/^[?.,!:;]/.test(w) ? ' ' : '') + w;

// ---------------------------------------------------------------------------
// World: one scatter chart (world units equal screen pixels at zoom 1) with the
// cafe shopfront above its top-right corner. Customers are chart values in
// content.json; everything below is computed from them.
// ---------------------------------------------------------------------------

type P = {x: number; y: number};
const CH = content.chart;
const PLOT = {x0: 210, y0: 1230, x1: 950, y1: 550};
const toWorld = (d: number[]): P => ({x: lerp(PLOT.x0, PLOT.x1, d[0] / CH.xMax), y: lerp(PLOT.y0, PLOT.y1, d[1] / CH.yMax)});
const dist = (a: P, b: P) => Math.hypot(a.x - b.x, a.y - b.y);
const mix = (a: P, b: P, t: number): P => ({x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t)});
const mean = (ps: P[]): P => ({x: ps.reduce((s, p) => s + p.x, 0) / ps.length, y: ps.reduce((s, p) => s + p.y, 0) / ps.length});

const DOTS = content.customers.map(toWorld);
const K = content.startCenters.length; // shapes and colors exist for three groups
const EXAMPLE = content.example.customer;
const SHOP = {x: 790, y: 235};
const DOOR = {x: 790, y: 301};
const BADGE = {right: 996, y: 604}; // free top-right corner of the chart (many visits, big spend: no customers)

// Real k-means, measured on the chart as drawn (both axes scaled to the plot, so "nearest" is what the eye sees).
// Pass r assigns every dot to its nearest center, then the centers move to the mean of their dots.
// It stops at the first pass in which no dot switches. Start centers are fixed in content.json.
const ROUNDS = (() => {
	const rounds: {centers: P[]; assign: number[]}[] = [];
	let centers = content.startCenters.map(toWorld);
	for (let r = 0; r < 50; r++) {
		const assign = DOTS.map((p) => centers.reduce((best, c, k) => (dist(p, c) < dist(p, centers[best]) ? k : best), 0));
		rounds.push({centers, assign});
		if (r > 0 && assign.every((g, i) => g === rounds[r - 1].assign[i])) break;
		centers = centers.map((c, k) => {
			const own = DOTS.filter((_, i) => assign[i] === k);
			return own.length ? mean(own) : c;
		});
	}
	return rounds;
})();
const LAST = ROUNDS.length - 1; // the settled pass: same groups as the pass before
// Self-check: every pass uses the nearest center, and the run really settled.
ROUNDS.forEach(({centers, assign}, r) =>
	assign.forEach((g, i) => {
		if (centers.some((c) => dist(DOTS[i], c) < dist(DOTS[i], centers[g]) - 1e-9)) throw new Error(`k-means: dot ${i} not nearest in pass ${r}`);
	}),
);
if (LAST < 2 || ROUNDS[LAST].assign.some((g, i) => g !== ROUNDS[LAST - 1].assign[i])) throw new Error('k-means did not settle as the storyboard needs');

const FINAL = ROUNDS[LAST];
const flippers = (r: number) => DOTS.map((_, i) => i).filter((i) => ROUNDS[r].assign[i] !== ROUNDS[r - 1].assign[i]);

// Timing of the two steps. ASSIGN_F[r]: dots join their nearest center. MOVE_F[r]: centers slide to the mean.
// Passes 2.. share scene 8's window evenly, so a different dataset still plays in order.
const FOCUS = DOTS.reduce((b, p, i) => (dist(p, mean(ROUNDS[0].centers)) < dist(DOTS[b], mean(ROUNDS[0].centers)) ? i : b), 0);
const LOOP_STEP = 94 / Math.max(1, LAST - 2);
const ASSIGN_F = ROUNDS.map((_, r) => (r === 0 ? S[4] + 88 : r === 1 ? S[6] + 34 : r === LAST ? S[8] + 10 : S[7] + 52 + (r - 2) * LOOP_STEP));
const MOVE_F = ROUNDS.map((_, r) => (r === 0 ? S[5] + 15 : r === 1 ? S[7] + 18 : ASSIGN_F[r] + LOOP_STEP * 0.45));
const moveStart = (r: number, k: number) => MOVE_F[r] + (r === 0 ? k * 38 : 0); // first jump: one center after the other
const moveDur = (r: number) => (r === 0 ? 30 : 22);
const centerAt = (k: number, f: number): P => {
	let p = ROUNDS[0].centers[k];
	for (let r = 0; r < LAST; r++) {
		const a = moveStart(r, k);
		if (f >= a) p = mix(ROUNDS[r].centers[k], ROUNDS[r + 1].centers[k], kf(f, [a, a + moveDur(r)], [0, 1]));
	}
	return p;
};

// When each dot takes a group: the first pass sweeps across the chart left to right, later passes flip one dot after another.
const joinFrame = (i: number) => (i === FOCUS ? S[4] + 56 : ASSIGN_F[0] + ((DOTS[i].x - PLOT.x0) / (PLOT.x1 - PLOT.x0)) * 40);
const flipFrame = (r: number, i: number) => ASSIGN_F[r] + flippers(r).indexOf(i) * 8 + (r === 1 ? 18 : 0);
const EVENTS = DOTS.map((_, i) => {
	const ev = [{f: joinFrame(i) + 8, g: ROUNDS[0].assign[i]}];
	for (let r = 1; r < LAST; r++) if (ROUNDS[r].assign[i] !== ROUNDS[r - 1].assign[i]) ev.push({f: flipFrame(r, i), g: ROUNDS[r].assign[i]});
	return ev;
});

// Dots leave the shop door: the example customer first, a few in the hook, the rest once the axes are labelled.
const ORDER = DOTS.map((_, i) => i).filter((i) => i !== EXAMPLE).sort((a, b) => ((a * 7) % 29) - ((b * 7) % 29));
const DROP = DOTS.map((_, i) => {
	const j = ORDER.indexOf(i);
	if (i === EXAMPLE) return {a: S[0] + 50, d: 50};
	return j < 8 ? {a: S[0] + 64 + j * 6, d: 44} : {a: S[1] + 72 + (j - 8) * 2, d: 34};
});

// Shapes: one outline of 24 points per kind, so a dot can morph between them.
// kind 0 = customer without a group, 1 = navy circle, 2 = violet rounded square, 3 = white triangle with a purple outline.
const shapeR = (kind: number, th: number) => {
	if (kind === 2) return 0.92 / Math.max(Math.abs(Math.cos(th)), Math.abs(Math.sin(th)));
	if (kind === 3) {
		const third = (2 * Math.PI) / 3;
		const phi = (((th + Math.PI / 2) % third) + third) % third;
		return (1.5 * 0.5) / Math.cos(phi - Math.PI / 3);
	}
	return 1;
};
const shapePath = (from: number, to: number, t: number, size: number) =>
	'M ' +
	Array.from({length: 24}, (_, k) => {
		const th = -Math.PI / 2 + (k * Math.PI) / 12;
		const r = lerp(shapeR(from, th), shapeR(to, th), t) * size;
		return `${(r * Math.cos(th)).toFixed(2)} ${(r * Math.sin(th) + (lerp(from === 3 ? 0.2 : 0, to === 3 ? 0.2 : 0, t)) * size).toFixed(2)}`;
	}).join(' L ') +
	' Z';
const KIND = {
	fill: [C.card, C.navy, C.violet, C.card],
	stroke: [C.navy, C.navy, C.violet, C.purple],
	width: [4, 4, 4, 5],
};
const GROUP_COLOR = [C.navy, C.violet, C.purple];

// Rounded outline around a group: its convex hull, pushed out by `pad` with round corners.
const outlinePath = (pts: P[], pad: number) => {
	const s = [...pts].sort((a, b) => a.x - b.x || a.y - b.y);
	const cross = (o: P, a: P, b: P) => (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
	const half = (list: P[]) =>
		list.reduce<P[]>((h, p) => {
			while (h.length >= 2 && cross(h[h.length - 2], h[h.length - 1], p) <= 0) h.pop();
			h.push(p);
			return h;
		}, []);
	const hull = [...half(s).slice(0, -1), ...half([...s].reverse()).slice(0, -1)]; // ponytail: needs 3+ dots not on one line
	const c = mean(hull);
	const edges = hull.map((a, i) => {
		const b = hull[(i + 1) % hull.length];
		const len = dist(a, b);
		let n = {x: (b.y - a.y) / len, y: -(b.x - a.x) / len};
		if (n.x * ((a.x + b.x) / 2 - c.x) + n.y * ((a.y + b.y) / 2 - c.y) < 0) n = {x: -n.x, y: -n.y};
		return [{x: a.x + n.x * pad, y: a.y + n.y * pad}, {x: b.x + n.x * pad, y: b.y + n.y * pad}];
	});
	const area = hull.reduce((sum, a, i) => sum + cross({x: 0, y: 0}, a, hull[(i + 1) % hull.length]), 0);
	return edges.map(([a, b], i) => `${i ? `A ${pad} ${pad} 0 0 ${area > 0 ? 1 : 0}` : 'M'} ${a.x.toFixed(1)} ${a.y.toFixed(1)} L ${b.x.toFixed(1)} ${b.y.toFixed(1)}`).join(' ')
		+ ` A ${pad} ${pad} 0 0 ${area > 0 ? 1 : 0} ${edges[0][0].x.toFixed(1)} ${edges[0][0].y.toFixed(1)} Z`;
};
const GROUP_DOTS = Array.from({length: K}, (_, k) => DOTS.filter((_, i) => FINAL.assign[i] === k));
const OUTLINES = GROUP_DOTS.map((g) => outlinePath(g, 40));

// The shop owner names the groups (people, not the computer): most visits, biggest spend, the rest.
const NAMED = (() => {
	const ids = Array.from({length: K}, (_, k) => k);
	const most = ids.reduce((b, k) => (FINAL.centers[k].x > FINAL.centers[b].x ? k : b));
	const rest = ids.filter((k) => k !== most);
	const big = rest.reduce((b, k) => (FINAL.centers[k].y < FINAL.centers[b].y ? k : b));
	return [
		{g: most, name: content.groupNames.mostVisits},
		{g: big, name: content.groupNames.biggestSpend},
		...rest.filter((k) => k !== big).map((g) => ({g, name: content.groupNames.rest})),
	];
})();
// Each offer card lands just outside its group, on the side facing the middle of the chart.
const OFFERS = NAMED.map(({g}, n) => {
	const c = FINAL.centers[g];
	const to = {x: 720, y: 690};
	const dir = {x: (to.x - c.x) / dist(c, to), y: (to.y - c.y) / dist(c, to)};
	const reach = Math.max(...GROUP_DOTS[g].map((p) => (p.x - c.x) * dir.x + (p.y - c.y) * dir.y));
	const land = {x: c.x + dir.x * (reach + 112), y: c.y + dir.y * (reach + 112)};
	return {g, land, ctrl: {x: lerp(DOOR.x, land.x, 0.1), y: lerp(DOOR.y, land.y, 0.7)}, a: S[10] + 40 + n * 42};
});
const bezier = (a: P, c: P, b: P, t: number): P => mix(mix(a, c, t), mix(c, b, t), t);

// ---------------------------------------------------------------------------
// Camera: opens on the shopfront, tilts down to the chart, pushes in gently on
// the example customer, one dot's measuring lines and the dots that switch,
// then pulls back far enough to bring the shop back for the offers.
// Push-ins are clamped so both axis titles stay in frame.
// ---------------------------------------------------------------------------

const frameCam = (x: number, y: number, s: number) => ({x: Math.min(x, 84 + 460 / s), y: Math.max(y, 1352 - 495 / s), s});
const FULL = {x: 540, y: 890, s: 1};
const CAMS = (() => {
	const ex = frameCam(DOTS[EXAMPLE].x - 230, DOTS[EXAMPLE].y - 115, 1.2);
	const focus = frameCam(lerp(580, DOTS[FOCUS].x, 0.5), lerp(890, DOTS[FOCUS].y, 0.5), 1.1);
	const fl = flippers(1).map((i) => DOTS[i]);
	const box = [...fl, ...Array.from(new Set(flippers(1).flatMap((i) => [ROUNDS[0].assign[i], ROUNDS[1].assign[i]]))).map((k) => ROUNDS[1].centers[k])];
	const [x0, x1, y0, y1] = [Math.min(...box.map((p) => p.x)), Math.max(...box.map((p) => p.x)), Math.min(...box.map((p) => p.y)), Math.max(...box.map((p) => p.y))];
	const sw = fl.length ? frameCam((x0 + x1) / 2, (y0 + y1) / 2, Math.max(1, Math.min(1.35, 800 / (x1 - x0 + 260), 880 / (y1 - y0 + 260)))) : FULL;
	return {open: {x: 760, y: 440, s: 1.1}, ex, focus, sw, wide: {x: 540, y: 765, s: 0.78}};
})();
const camera = (f: number) => {
	const keys: [number, {x: number; y: number; s: number}][] = [
		[S[0] + 58, CAMS.open], [S[0] + 110, FULL],
		[S[1] + 4, FULL], [S[1] + 34, CAMS.ex], [S[1] + 66, CAMS.ex], [S[1] + 96, FULL],
		[S[4] + 2, FULL], [S[4] + 26, CAMS.focus], [S[4] + 66, CAMS.focus], [S[4] + 90, FULL],
		[S[6] + 2, FULL], [S[6] + 28, CAMS.sw], [S[7], CAMS.sw], [S[7] + 24, FULL],
		[S[10] + 2, FULL], [S[10] + 32, CAMS.wide],
	];
	const t = keys.map((k) => k[0]);
	return {x: kf(f, t, keys.map((k) => k[1].x)), y: kf(f, t, keys.map((k) => k[1].y)), s: kf(f, t, keys.map((k) => k[1].s))};
};

// ---------------------------------------------------------------------------
// Components
// ---------------------------------------------------------------------------

// A stroke that draws itself (one technique per stroke: pathLength + dash offset).
const Draw: React.FC<{d: string; p: number; stroke: string; w?: number; o?: number; fill?: string; fillO?: number}> = ({d, p, stroke, w = 5, o = 1, fill = 'none', fillO = 0}) => (
	<path d={d} fill={fill} fillOpacity={fillO} stroke={stroke} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round"
		pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - p} opacity={p > 0.001 ? o : 0} />
);
const arrowHead = (x: number, y: number, ang: number, size = 16) =>
	`M ${x + size * Math.cos(ang + 2.5)} ${y + size * Math.sin(ang + 2.5)} L ${x} ${y} L ${x + size * Math.cos(ang - 2.5)} ${y + size * Math.sin(ang - 2.5)}`;
const rectPath = (x: number, y: number, w: number, h: number, r: number) =>
	`M ${x + r} ${y} H ${x + w - r} Q ${x + w} ${y} ${x + w} ${y + r} V ${y + h - r} Q ${x + w} ${y + h} ${x + w - r} ${y + h} H ${x + r} Q ${x} ${y + h} ${x} ${y + h - r} V ${y + r} Q ${x} ${y} ${x + r} ${y} Z`;
// A curve from a to b, as far as t (the moving object sits exactly on its tip).
const curveTo = (a: P, c: P, b: P, t: number) => 'M ' + Array.from({length: 17}, (_, j) => bezier(a, c, b, (t * j) / 16)).map((p) => `${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' L ');

// The cafe: outline draws, then a soft fill. It is where the customer dots and the offers come from.
const Shop: React.FC<{f: number}> = ({f}) => {
	const p = enter(f, [S[0] + 5, S[0] + 35], [0, 1]);
	const fill = enter(f, [S[0] + 24, S[0] + 40], [0, 1]);
	const awning = 'M -114 -100 H 114 V -54 ' + 'q -19 24 -38 0 '.repeat(6) + 'Z';
	return (
		<g transform={`translate(${SHOP.x} ${SHOP.y})`}>
			<Draw d={rectPath(-100, -60, 200, 160, 12)} p={p} stroke={C.navy} fill={C.card} fillO={fill} />
			<Draw d={awning} p={p} stroke={C.navy} fill={C.lavender} fillO={fill} />
			<Draw d={rectPath(-30, 12, 60, 88, 8)} p={p} stroke={C.navy} w={4} fill={C.lavenderTint} fillO={fill} />
			{[-84, 44].map((x) => <Draw key={x} d={rectPath(x, -8, 40, 52, 6)} p={p} stroke={C.navy} w={4} fill={C.lavenderTint} fillO={fill} />)}
			<circle cx={16} cy={58} r={4} fill={C.navy} opacity={fill} />
		</g>
	);
};

// The scatter chart frame: axes grow from the corner, then tick numbers and titles write on.
const Chart: React.FC<{f: number}> = ({f}) => {
	const ax = enter(f, [S[0] + 82, S[0] + 112], [0, 1]);
	const tick = (n: number) => enter(f, [S[1] + 4 + n * 2, S[1] + 18 + n * 2], [0, 1]);
	const title = (d: number) => enter(f, [S[1] + 10 + d, S[1] + 30 + d], [0, 1]);
	const hl = fade(f, S[1] + 44, S[1] + 106, 10); // the example customer's value on the bottom axis
	const ex = content.customers[EXAMPLE];
	const tx = (v: number) => lerp(PLOT.x0, PLOT.x1, v / CH.xMax);
	const ty = (v: number) => lerp(PLOT.y0, PLOT.y1, v / CH.yMax);
	return (
		<g>
			{CH.yTicks.map((v, n) => <line key={v} x1={PLOT.x0} x2={PLOT.x1} y1={ty(v)} y2={ty(v)} stroke={C.grid} strokeWidth={2.5} opacity={tick(n)} />)}
			{CH.xTicks.filter((v) => v > 0).map((v, n) => <line key={v} x1={tx(v)} x2={tx(v)} y1={PLOT.y0} y2={PLOT.y1} stroke={C.grid} strokeWidth={2.5} opacity={tick(n)} />)}
			<g opacity={ax > 0 ? 1 : 0} stroke={C.navy} strokeWidth={5} strokeLinecap="round">
				<line x1={PLOT.x0} y1={PLOT.y0} x2={PLOT.x0} y2={lerp(PLOT.y0, PLOT.y1 - 24, ax)} />
				<line x1={PLOT.x0} y1={PLOT.y0} x2={lerp(PLOT.x0, PLOT.x1 + 24, ax)} y2={PLOT.y0} />
			</g>
			{CH.xTicks.map((v, n) => (
				<text key={v} x={tx(v)} y={PLOT.y0 + 44} fontSize={28} fontWeight={v === ex[0] && hl > 0.5 ? 700 : 500} textAnchor="middle"
					fill={v === ex[0] ? mixColor(C.navy, C.violet, hl) : C.navy} opacity={tick(n)}>{v}</text>
			))}
			{CH.yTicks.map((v, n) => (
				<text key={v} x={PLOT.x0 - 16} y={ty(v) + 10} fontSize={28} fontWeight={500} textAnchor="end" fill={C.navy} opacity={tick(n)}>{CH.yPrefix}{v}</text>
			))}
			<clipPath id="xTitle"><rect x={(PLOT.x0 + PLOT.x1) / 2 - 170} y={PLOT.y0 + 70} width={340 * title(0)} height={50} /></clipPath>
			<text x={(PLOT.x0 + PLOT.x1) / 2} y={PLOT.y0 + 106} clipPath="url(#xTitle)" fontSize={32} fontWeight={600} textAnchor="middle" fill={C.navy}>{CH.xTitle}</text>
			<clipPath id="yTitle"><rect x={-160} y={-34} width={320 * title(6)} height={48} /></clipPath>
			<text transform={`translate(108 ${(PLOT.y0 + PLOT.y1) / 2}) rotate(-90)`} clipPath="url(#yTitle)" fontSize={32} fontWeight={600} textAnchor="middle" fill={C.navy}>{CH.yTitle}</text>
		</g>
	);
};

// Scene 2: two violet guide lines read the example customer's place off both axes.
const Guides: React.FC<{f: number}> = ({f}) => {
	const a = S[1] + 32;
	const o = kf(f, [S[1] + 96, S[1] + 106], [1, 0], EASE.in);
	if (f < a || o <= 0) return null;
	const d = DOTS[EXAMPLE];
	const p = enter(f, [a, a + 24], [0, 1]);
	return (
		<g opacity={o} stroke={C.violet} strokeWidth={4} strokeLinecap="round">
			<line x1={d.x} y1={d.y} x2={d.x} y2={lerp(d.y, PLOT.y0, p)} />
			<line x1={d.x} y1={d.y} x2={lerp(d.x, PLOT.x0, p)} y2={d.y} />
			<text x={PLOT.x0 - 16} y={d.y + 10} fontSize={28} fontWeight={700} textAnchor="end" fill={C.violet} stroke="none" opacity={enter(f, [a + 12, a + 24], [0, 1])}>
				{CH.yPrefix}{content.customers[EXAMPLE][1]}
			</text>
		</g>
	);
};

// Scene 3: a lasso tries one area, unwinds, tries another, unwinds: by eye the groups are not obvious.
const Lasso: React.FC<{f: number}> = ({f}) => (
	<g>
		{content.lassos.map((l, n) => {
			const a = S[2] + 12 + n * 46;
			const p = kf(f, [a, a + 24, a + 30, a + 42], [0, 0.8, 0.8, 0], [EASE.out, EASE.linear, EASE.in]);
			const c = toWorld([l.visits, l.spend]);
			return (
				<ellipse key={n} cx={c.x} cy={c.y} rx={(l.halfVisits / CH.xMax) * (PLOT.x1 - PLOT.x0)} ry={(l.halfSpend / CH.yMax) * (PLOT.y0 - PLOT.y1)} fill="none" stroke={C.violet} strokeWidth={5}
					strokeLinecap="round" pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - p} opacity={p > 0.001 ? 1 : 0} />
			);
		})}
	</g>
);
const Q = {x: 750, y: 700};
const QuestionMark: React.FC<{f: number}> = ({f}) => {
	const o = fade(f, S[2] + 98, S[3] + 62, 16, 10);
	return <text x={Q.x} y={Q.y + 52 + (1 - enter(f, [S[2] + 98, S[2] + 114], [0, 1])) * 24} fontSize={150} fontWeight={700} textAnchor="middle" fill={C.violet} opacity={o}>?</text>;
};

// Dashed navy trail behind a jumping center, and a ring where it stood.
const Trails: React.FC<{f: number}> = ({f}) => (
	<g>
		{ROUNDS.slice(0, LAST).flatMap((round, r) =>
			round.centers.map((from, k) => {
				const a = moveStart(r, k);
				const to = ROUNDS[r + 1].centers[k];
				const end = r + 1 < LAST ? MOVE_F[r + 1] : S[8] + 30;
				const o = kf(f, [end, end + 10], [1, 0], EASE.in);
				if (f < a || o <= 0 || dist(from, to) < 4) return null;
				const cur = mix(from, to, kf(f, [a, a + moveDur(r)], [0, 1]));
				return (
					<g key={`${r}-${k}`} opacity={o}>
						<line x1={from.x} y1={from.y} x2={cur.x} y2={cur.y} stroke={C.navy} strokeWidth={5} strokeDasharray="12 14" strokeLinecap="round" />
						<circle cx={from.x} cy={from.y} r={11} fill={C.background} stroke={C.navy} strokeWidth={4} opacity={enter(f, [a, a + 12], [0, 1])} />
					</g>
				);
			}),
		)}
	</g>
);

// Scene 5: the other two measuring lines from the focus dot; they retract once the shortest is found.
const MeasureLines: React.FC<{f: number}> = ({f}) => (
	<g>
		{ROUNDS[0].centers.map((c, k) => {
			const a = S[4] + 24 + k * 5;
			const p = Math.min(enter(f, [a, a + 16], [0, 1]), kf(f, [S[4] + 56, S[4] + 68], [1, 0], EASE.in));
			if (k === ROUNDS[0].assign[FOCUS] || f < a || p <= 0) return null;
			const d = DOTS[FOCUS];
			return <line key={k} x1={d.x} y1={d.y} x2={lerp(d.x, c.x, p)} y2={lerp(d.y, c.y, p)} stroke={C.navy} strokeWidth={4} strokeLinecap="round" />;
		})}
	</g>
);

// A violet line from each dot to its nearest center. It follows the center when it jumps;
// for a dot that switches in pass 2 it swings across to the new center.
const NearLines: React.FC<{f: number}> = ({f}) => (
	<g>
		{DOTS.map((d, i) => {
			const g = ROUNDS[0].assign[i];
			const a = i === FOCUS ? S[4] + 24 + g * 5 : joinFrame(i);
			const sw = flippers(1).includes(i);
			const out = sw ? kf(f, [S[6] + 100, S[6] + 112], [1, 0], EASE.in) : kf(f, [S[5] + 128, S[5] + 140], [1, 0], EASE.in);
			if (f < a || out <= 0) return null;
			const grow = enter(f, [a, a + (i === FOCUS ? 16 : 12)], [0, 1]);
			let c = centerAt(g, f);
			if (sw) c = mix(c, centerAt(ROUNDS[1].assign[i], f), kf(f, [flipFrame(1, i) - 18, flipFrame(1, i)], [0, 1]));
			const found = i === FOCUS ? kf(f, [S[4] + 46, S[4] + 56], [0, 1]) : 1;
			const hot = i === FOCUS ? kf(f, [S[4] + 46, S[4] + 56, ASSIGN_F[0], ASSIGN_F[0] + 12], [0, 1, 1, 0]) : sw ? kf(f, [S[6] + 8, S[6] + 20], [0, 1]) : 0;
			return (
				<line key={i} x1={d.x} y1={d.y} x2={lerp(d.x, c.x, grow)} y2={lerp(d.y, c.y, grow)} stroke={mixColor(C.navy, C.violet, found)}
					strokeWidth={lerp(4, 6, hot)} strokeLinecap="round" opacity={(i === FOCUS && found < 1 ? 1 : lerp(0.5, 1, hot)) * out} />
			);
		})}
	</g>
);

// A violet ring pulse on every dot that switches groups.
const Pulses: React.FC<{f: number}> = ({f}) => (
	<g>
		{ROUNDS.slice(1, LAST).flatMap((_, n) =>
			flippers(n + 1).map((i) => {
				const p = (f - flipFrame(n + 1, i)) / 16;
				if (p < 0 || p > 1) return null;
				return <circle key={`${n}-${i}`} cx={DOTS[i].x} cy={DOTS[i].y} r={lerp(16, 40, p)} fill="none" stroke={C.violet} strokeWidth={5} opacity={1 - p} />;
			}),
		)}
	</g>
);

// One customer. It falls from the shop door along a purple curve, then keeps its place for the whole video
// and only changes shape and color when it joins or switches groups.
const Dot: React.FC<{f: number; i: number}> = ({f, i}) => {
	const {a, d} = DROP[i];
	if (f < a) return null;
	const t = kf(f, [a, a + d], [0, 1]);
	const ctrl = {x: DOTS[i].x, y: DOOR.y + 30};
	const p = bezier(DOOR, ctrl, DOTS[i], t);
	const ev = EVENTS[i];
	let e = -1;
	ev.forEach((x, n) => { if (f >= x.f) e = n; });
	const from = e > 0 ? ev[e - 1].g + 1 : 0;
	const to = e >= 0 ? ev[e].g + 1 : 0;
	const m = e >= 0 ? kf(f, [ev[e].f, ev[e].f + 18], [0, 1]) : 0;
	const trail = kf(f, [a + d, a + d + 10], [0.8, 0], EASE.in);
	return (
		<g>
			{trail > 0 && <path d={curveTo(DOOR, ctrl, DOTS[i], t)} fill="none" stroke={C.purple} strokeWidth={5} strokeLinecap="round" strokeLinejoin="round" opacity={trail} />}
			<path transform={`translate(${p.x} ${p.y})`} d={shapePath(from, to, m, 13)} fill={mixColor(KIND.fill[from], KIND.fill[to], m)} stroke={mixColor(KIND.stroke[from], KIND.stroke[to], m)}
				strokeWidth={lerp(KIND.width[from], KIND.width[to], m)} strokeLinejoin="round" opacity={enter(f, [a, a + 8], [0, 1])} />
		</g>
	);
};

// A center marker: twice a dot's size, navy outline, plus sign, lavender glow. It comes out of the question mark.
const Center: React.FC<{f: number; k: number}> = ({f, k}) => {
	const a = S[3] + 52 + k * 12;
	if (f < a) return null;
	const e = enter(f, [a, a + 26], [0, 1]);
	const p = f < a + 26 ? mix(Q, ROUNDS[0].centers[k], e) : centerAt(k, f);
	const calm = Math.max(kf(f, [S[8] + 12, S[8] + 20, S[8] + 30], [0, 1, 0]), kf(f, [S[9] + 112, S[9] + 120, S[9] + 130], [0, 1, 0]));
	const dy = k === 2 ? 5 : 0;
	return (
		<g transform={`translate(${p.x} ${p.y}) scale(${lerp(0.96, 1, e)})`} opacity={e}>
			<circle r={46 + calm * 16} fill={C.lavender} opacity={0.6 + calm * 0.4} filter="url(#blur)" />
			<path d={shapePath(k + 1, k + 1, 0, 27)} fill={GROUP_COLOR[k]} stroke={C.navy} strokeWidth={6} strokeLinejoin="round" />
			<path d={`M -11 ${dy} H 11 M 0 ${dy - 11} V ${dy + 11}`} stroke="#fff" strokeWidth={5} strokeLinecap="round" />
		</g>
	);
};

// Scene 9: an outline in each group's own color draws around its dots.
const Outlines: React.FC<{f: number}> = ({f}) => (
	<g>
		{OUTLINES.map((d, k) => {
			const a = S[8] + 50 + k * 10;
			const t = OFFERS.find((o) => o.g === k)?.a ?? END;
			const thick = Math.max(kf(f, [S[9] + 50, S[9] + 58, S[9] + 68], [0, 1, 0]), kf(f, [t, t + 8, t + 18], [0, 1, 0]));
			return <Draw key={k} d={d} p={enter(f, [a, a + 30], [0, 1])} stroke={GROUP_COLOR[k]} w={5 + thick * 4} />;
		})}
	</g>
);

// Label card: off-white, violet outline, navy text. Right-aligned in the chart's free corner unless cx is given.
const Badge: React.FC<{f: number; text: string; a: number; b: number; cx?: number; y?: number; k?: number; icon?: number}> = ({f, text, a, b, cx, y = BADGE.y, k = 1, icon}) => {
	const o = fade(f, a, b);
	if (o <= 0) return null;
	const pad = icon === undefined ? 0 : 46;
	const w = text.length * 16 + 40 + pad;
	const x = cx ?? BADGE.right - (w * k) / 2;
	return (
		<g transform={`translate(${x} ${y + (1 - enter(f, [a, a + 16], [0, 1])) * 24}) scale(${k})`} opacity={o}>
			<rect x={-w / 2} y={-32} width={w} height={64} rx={16} fill={C.background} stroke={C.violet} strokeWidth={4} filter="url(#soft)" />
			{icon !== undefined && (
				<path transform={`translate(${-w / 2 + 40} 0)`} d={shapePath(icon + 1, icon + 1, 0, 13)} fill={KIND.fill[icon + 1]} stroke={KIND.stroke[icon + 1]} strokeWidth={KIND.width[icon + 1]} strokeLinejoin="round" />
			)}
			<text x={pad / 2} y={11} fontSize={32} fontWeight={600} textAnchor="middle" fill={C.navy}>{text}</text>
		</g>
	);
};

// Scenes 8-9: round counter with two arrows chasing each other; they slow down and close into a check mark.
const Counter: React.FC<{f: number}> = ({f}) => {
	const [a, b] = [S[7] + 8, S[9] + 16];
	const o = fade(f, a, b);
	if (o <= 0) return null;
	const round = 1 + ASSIGN_F.filter((t, r) => r >= 1 && r < LAST && f >= t).length;
	const stop = S[8] + 10;
	const angle = (Math.min(f, stop) - a) * 5 + enter(f, [stop, stop + 30], [0, 70]);
	const arrows = kf(f, [S[8] + 34, S[8] + 42], [1, 0], EASE.in);
	const done = enter(f, [S[8] + 42, S[8] + 58], [0, 1]);
	const w = 300;
	const pt = (deg: number) => [17 * Math.cos((deg * Math.PI) / 180), 17 * Math.sin((deg * Math.PI) / 180)];
	const arc = (start: number) => {
		const [p0, p1] = [pt(start), pt(start + 130)];
		return `M ${p0.join(' ')} A 17 17 0 0 1 ${p1.join(' ')} ${arrowHead(p1[0], p1[1], ((start + 130 + 90) * Math.PI) / 180, 9)}`;
	};
	return (
		<g transform={`translate(${BADGE.right - w / 2} ${BADGE.y + (1 - enter(f, [a, a + 16], [0, 1])) * 24})`} opacity={o}>
			<rect x={-w / 2} y={-32} width={w} height={64} rx={16} fill={C.background} stroke={C.violet} strokeWidth={4} filter="url(#soft)" />
			<g transform={`translate(${-w / 2 + 46} 0)`}>
				<g transform={`rotate(${angle})`} opacity={arrows}>
					{[0, 180].map((s) => <path key={s} d={arc(s)} fill="none" stroke={C.violet} strokeWidth={5} strokeLinecap="round" strokeLinejoin="round" />)}
				</g>
				<Draw d="M -14 1 L -4 11 L 15 -11" p={done} stroke={C.violet} w={6} />
			</g>
			<text x={30} y={11} fontSize={32} fontWeight={600} textAnchor="middle" fill={C.navy} opacity={1 - done}>{content.labels.round} {round}</text>
			<text x={30} y={11} fontSize={32} fontWeight={600} textAnchor="middle" fill={C.navy} opacity={done}>{content.labels.settled}</text>
		</g>
	);
};

// Scene 11: an offer card travels from the shop to each group and takes that group's shape as its icon.
const Offers: React.FC<{f: number}> = ({f}) => (
	<g>
		{OFFERS.map(({g, land, ctrl, a}, n) => {
			if (f < a) return null;
			const t = kf(f, [a, a + 30], [0, 1]);
			const p = bezier(DOOR, ctrl, land, t);
			const icon = enter(f, [a + 30, a + 44], [0, 1]);
			return (
				<g key={n}>
					<path d={curveTo(DOOR, ctrl, land, t)} fill="none" stroke={C.violet} strokeWidth={5} strokeLinecap="round" strokeLinejoin="round" opacity={0.85} />
					<g transform={`translate(${p.x} ${p.y})`} opacity={enter(f, [a, a + 8], [0, 1])}>
						<rect x={-40} y={-29} width={80} height={58} rx={12} fill={C.card} stroke={C.navy} strokeWidth={4} filter="url(#soft)" />
						<path transform={`scale(${lerp(0.96, 1, icon)})`} d={shapePath(g + 1, g + 1, 0, 13)} fill={KIND.fill[g + 1]} stroke={KIND.stroke[g + 1]} strokeWidth={KIND.width[g + 1]} strokeLinejoin="round" opacity={icon} />
					</g>
				</g>
			);
		})}
	</g>
);

// Headline: left-aligned, masked reveal line by line, *words* in brand violet.
const Headline: React.FC<{f: number}> = ({f}) => (
	<>
		{content.scenes.map((sc, i) => {
			if (!sc.headline) return null;
			const a = S[i];
			const b = sceneEnd(i);
			const out = kf(f, [b - 8, b], [1, 0], EASE.in);
			if (f < a || out <= 0) return null;
			return (
				<g key={i} opacity={out}>
					{sc.headline.split('\n').map((line, li) => {
						const y = HEADLINE_Y + li * 72;
						const rise = enter(f, [a + li * 4, a + 18 + li * 4], [74, 0]);
						return (
							<g key={li}>
								<clipPath id={`hl-${i}-${li}`}>
									<rect x={0} y={y - 62} width={1080} height={80} />
								</clipPath>
								<text x={SAFE.left} y={y + rise} clipPath={`url(#hl-${i}-${li})`} fontSize={58} fontWeight={700} fill={C.navy}>
									{parseMarked(line).map(({w, hl}, k) => (
										<tspan key={k} fill={hl ? C.violet : C.navy}>{spaced(w, k)}</tspan>
									))}
								</text>
							</g>
						);
					})}
				</g>
			);
		})}
	</>
);

// Subtitles: navy bar in the lower safe area, word-group reveal synced to the voiceover.
const Subtitles: React.FC<{f: number}> = ({f}) => (
	<>
		{content.scenes.map((sc, i) => {
			const start = sc.voStart * FPS;
			const dur = ((voTiming as number[])[i] ?? 3) * FPS;
			const end = Math.min(sceneEnd(i) - 2, start + dur + 18);
			const o = kf(f, [start - 4, start + 4, end - 6, end], [0, 1, 1, 0]);
			if (o <= 0) return null;
			const words = parseMarked(sc.voiceover);
			const perLine = words.length > 7 || sc.voiceover.length > 40 ? Math.ceil(words.length / 2) : words.length;
			const lines = [words.slice(0, perLine), words.slice(perLine)].filter((l) => l.length);
			const h = 34 + lines.length * 54;
			let n = 0;
			return (
				<g key={i} opacity={o}>
					<rect x={SAFE.left} y={SUB_BOTTOM - h} width={SAFE.right - SAFE.left} height={h} rx={20} fill={C.navy} fillOpacity={0.88} />
					{lines.map((line, li) => (
						<text key={li} x={540} y={SUB_BOTTOM - h + 56 + li * 54} fontSize={40} fontWeight={600} textAnchor="middle">
							{line.map(({w, hl}, k) => {
								// Words reveal in groups of three, paced across the spoken line.
								const group = Math.floor(n++ / 3);
								const at = start + (group * 3 * dur) / words.length;
								return (
									<tspan key={k} fill={hl ? C.lavender : '#fff'} fillOpacity={enter(f, [at, at + 8], [0.25, 1])}>
										{spaced(w, k)}
									</tspan>
								);
							})}
						</text>
					))}
				</g>
			);
		})}
	</>
);

// Outro: the three center markers and the example customer slide into a row and stand up as the
// DataEntropy logo bars (four gradient bars above the wordmark, violet "E"), then the tagline and one CTA.
// Guideline motion: bars grow left to right, wordmark reveals after, soft violet glow.
const LOGO = {
	barW: 66,
	gap: 22,
	heights: [96, 156, 212, 276], // proportions of the logo image
	base: 700, // bar baseline (screen y)
	wordY: 832, // wordmark baseline
	wordSize: 104,
};
const LAST_SCENE = S[S.length - 1];
// Where the markers sit on screen when the outro starts (the camera is still by then).
const SEEDS = [...FINAL.centers, DOTS[EXAMPLE]]
	.map((p) => {
		const cam = camera(LAST_SCENE);
		return {x: 540 + (p.x - cam.x) * cam.s, y: CONTENT_CY + (p.y - cam.y) * cam.s};
	})
	.sort((a, b) => a.x - b.x);
const Outro: React.FC<{f: number}> = ({f}) => {
	const a = LAST_SCENE;
	if (f < a) return null;
	const {barW, gap, heights, base} = LOGO;
	const symbolW = heights.length * barW + (heights.length - 1) * gap;
	const left = 540 - symbolW / 2;
	const top = base - heights[heights.length - 1];
	const seed = enter(f, [a + 8, a + 20], [0, 1]);
	const gather = kf(f, [a + 10, a + 30], [0, 1]);
	const word = enter(f, [a + 60, a + 80], [0, 1]);
	const glow = kf(f, [a + 74, a + 83, a + 92], [0, 1, 0.35]);
	const tag = enter(f, [a + 74, a + 90], [0, 1]);
	const cta = enter(f, [a + 84, a + 102], [0, 1]);
	const arrow = kf(f, [a + 98, a + 116], [0, 10], EASE.inOut);
	return (
		<g>
			<linearGradient id="logoBars" gradientUnits="userSpaceOnUse" x1={left} y1={top} x2={left + symbolW} y2={base}>
				<stop offset="0" stopColor={C.lavender} />
				<stop offset="0.55" stopColor={C.purple} />
				<stop offset="1" stopColor={C.violet} />
			</linearGradient>
			<g filter={glow > 0.05 ? 'url(#glow)' : undefined}>
				{heights.map((bh, k) => {
					// Each bar starts where a marker was, slides into the row, then grows.
					const g = enter(f, [a + 30 + k * 7, a + 48 + k * 7], [0, 1]);
					const w = lerp(44, barW, gather);
					const h = w + (bh - barW) * g;
					const cx = lerp(SEEDS[k].x, left + k * (barW + gap) + barW / 2, gather);
					const bottom = lerp(SEEDS[k].y + 22, base, gather);
					return <rect key={k} x={cx - w / 2} y={bottom - h} width={w} height={h} rx={lerp(14, barW / 2, gather)} fill="url(#logoBars)" opacity={seed} />;
				})}
			</g>
			<clipPath id="wordmark">
				<rect x={540 - 400} y={LOGO.wordY - 110} width={800 * word} height={150} />
			</clipPath>
			<text x={540} y={LOGO.wordY} clipPath="url(#wordmark)" fontFamily={LOGO_FONT} fontSize={LOGO.wordSize} fontWeight={700}
				textAnchor="middle" fill={C.navy} letterSpacing={-1}>
				Data<tspan fill={C.purple}>E</tspan>ntropy
			</text>
			<text x={540} y={935 + (1 - tag) * 24} fontSize={34} fontWeight={500} textAnchor="middle" fill={C.muted} opacity={tag}>{content.brand.tagline}</text>
			<g opacity={cta} transform={`translate(0 ${(1 - cta) * 24})`}>
				<rect x={260} y={1000} width={560} height={100} rx={20} fill={C.violet} filter="url(#soft)" />
				<text x={520} y={1063} fontSize={38} fontWeight={600} textAnchor="middle" fill="#fff">{content.brand.cta}</text>
				<text x={745 + arrow} y={1063} fontSize={38} fontWeight={600} textAnchor="middle" fill="#fff">→</text>
			</g>
		</g>
	);
};

// ---------------------------------------------------------------------------

export const KMeansVideo: React.FC = () => {
	const f = useCurrentFrame();
	const cam = camera(f);
	const worldO = kf(f, [LAST_SCENE, LAST_SCENE + 18], [1, 0], EASE.in);
	const L = content.labels;
	const ex = DOTS[EXAMPLE];

	return (
		<AbsoluteFill style={{backgroundColor: C.background, fontFamily: FONT}}>
			<svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{fontFamily: FONT}}>
				<defs>
					<filter id="soft" x="-30%" y="-30%" width="160%" height="170%">
						<feDropShadow dx="0" dy="10" stdDeviation="14" floodColor={C.violet} floodOpacity="0.1" />
					</filter>
					<filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
						<feDropShadow dx="0" dy="0" stdDeviation="12" floodColor={C.violet} floodOpacity="0.35" />
					</filter>
					<filter id="blur" x="-60%" y="-60%" width="220%" height="220%">
						<feGaussianBlur stdDeviation="10" />
					</filter>
					<pattern id="dots" width={48} height={48} patternUnits="userSpaceOnUse">
						<circle cx={24} cy={24} r={2} fill={C.grid} />
					</pattern>
					<linearGradient id="worldFade" x1="0" y1="0" x2="0" y2="1920" gradientUnits="userSpaceOnUse">
						<stop offset={340 / 1920} stopColor="#fff" stopOpacity={0} />
						<stop offset={400 / 1920} stopColor="#fff" />
						<stop offset={1390 / 1920} stopColor="#fff" />
						<stop offset={1440 / 1920} stopColor="#fff" stopOpacity={0} />
					</linearGradient>
					<mask id="worldMask" maskUnits="userSpaceOnUse" x={0} y={0} width={1080} height={1920}>
						<rect width={1080} height={1920} fill="url(#worldFade)" />
					</mask>
					<radialGradient id="lavGlow" cx="0.85" cy="0.1" r="0.7">
						<stop offset="0" stopColor={C.lavender} stopOpacity={0.35} />
						<stop offset="1" stopColor={C.lavender} stopOpacity={0} />
					</radialGradient>
				</defs>
				<rect width={1080} height={1920} fill="url(#lavGlow)" />
				<g mask="url(#worldMask)">
				<g opacity={worldO} transform={`translate(${540 - cam.x * cam.s} ${CONTENT_CY - cam.y * cam.s}) scale(${cam.s})`}>
					<rect x={-1500} y={-1500} width={4000} height={5000} fill="url(#dots)" />
					<Shop f={f} />
					<Chart f={f} />
					<Outlines f={f} />
					<Trails f={f} />
					<NearLines f={f} />
					<MeasureLines f={f} />
					<Guides f={f} />
					{DOTS.map((_, i) => <Dot key={i} f={f} i={i} />)}
					<Pulses f={f} />
					<Lasso f={f} />
					<QuestionMark f={f} />
					{ROUNDS[0].centers.map((_, k) => <Center key={k} f={f} k={k} />)}
					<Offers f={f} />
					<Badge f={f} text={content.example.badge} a={S[1] + 20} b={S[1] + 70} cx={ex.x - 150} y={ex.y - 140} />
					<Badge f={f} text={L.center} a={S[3] + 105} b={S[4] - 6} />
					<Badge f={f} text={L.nearest} a={S[4] + 100} b={S[5] - 6} />
					<Badge f={f} text={L.middle} a={S[5] + 60} b={S[6] - 6} />
					<Counter f={f} />
					<Badge f={f} text={L.k.replace('{k}', String(K))} a={S[9] + 50} b={S[9] + 106} />
					<Badge f={f} text={L.mean} a={S[9] + 112} b={S[10] - 4} />
					{NAMED.map(({g, name}, n) => (
						<Badge key={n} f={f} text={name} icon={g} a={OFFERS[n].a} b={n + 1 < NAMED.length ? OFFERS[n + 1].a - 2 : LAST_SCENE + 6} cx={380} y={275} k={1.3} />
					))}
				</g>
				</g>
				<Outro f={f} />
				<Headline f={f} />
				<Subtitles f={f} />
			</svg>
			{content.scenes.map((sc, i) => (
				<Sequence key={i} from={Math.round(sc.voStart * FPS)}>
					<Audio src={staticFile(`vo/scene-${i + 1}.wav`)} />
				</Sequence>
			))}
			<Audio src={staticFile('music.wav')} />
		</AbsoluteFill>
	);
};
